import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.BH4HaZMQ.js";var i=JSON.parse(`{"title":"What is Vibator?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-vibator.md","filePath":"guide/what-is-vibator.md"}`),a={name:`guide/what-is-vibator.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-vibator" tabindex="-1">What is Vibator? <a class="header-anchor" href="#what-is-vibator" aria-label="Permalink to “What is Vibator?”">​</a></h1><p>Vibator is an unopinionated linter for JavaScript and TypeScript. It ships no rules of its own. You write custom rules for your own standards, and Vibator runs them across the project, reports each finding with the guideline that explains it, and fixes them on request.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to “The problem it solves”">​</a></h2><p>Vibator started as a way to hold coding agents to a project&#39;s standards. Style guidance written in prompts and guides is not actionable: an agent drifts from it as its context grows. Left alone, an agent checks these standards with throwaway scripts.</p><p>Vibator gives you a framework to encode a standard as a deterministic check with a guideline attached. When the check fails, the standard reaches the agent, and it fixes the problem at its source.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How it works”">​</a></h2><ul><li>A rule reads the project through the <code>vibator</code> namespace and returns findings. The namespace covers files, git, the shell, and more, so a rule does not need to reach for them directly.</li><li>The engine loop is thin: <code>check → write → recheck → report</code>. The only thing the framework imposes is the severity of a finding (<code>error</code>, <code>warn</code>, or <code>off</code>).</li><li>A rule sees every file at once, so it can make cross-file findings, not just judge one file in isolation.</li><li>You decide how a rule reads the project, whether it takes options, and whether it is fixable. You control the shape of its diagnostics.</li><li>Output is a readable terminal report, JSON, or SARIF for code scanning.</li></ul><h2 id="alongside-other-tools" tabindex="-1">Alongside other tools <a class="header-anchor" href="#alongside-other-tools" aria-label="Permalink to “Alongside other tools”">​</a></h2><p>Vibator runs next to your other linters. Keep a strict stack of Biome, knip, and dependency-cruiser, and use Vibator for the standards those tools do not reach.</p>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};